<?php
require __DIR__.'/client_profiles.php';
require_once APPPATH.'services/CompanyCustomerGroups.php';
require APPPATH.'services/CompanyCustomerGroupsSchema.php';
$id=$db->driver()==='sqlite'?'INTEGER PRIMARY KEY AUTOINCREMENT':'INT NOT NULL AUTO_INCREMENT PRIMARY KEY';
$db->query("CREATE TABLE {$p}customers_groups(id $id,name varchar(191) NOT NULL)");
$db->query("CREATE TABLE {$p}customer_groups(id $id,customer_id int NOT NULL,groupid int NOT NULL)");
if($db->driver()==='sqlite')$db->query("CREATE TABLE {$p}company_customer_group_owners(group_id int NOT NULL PRIMARY KEY,issuer_id int NOT NULL,FOREIGN KEY(group_id) REFERENCES {$p}customers_groups(id),FOREIGN KEY(issuer_id) REFERENCES {$p}issuers_registry(id))");
else CompanyCustomerGroupsSchema::ensure($db,$p);
unset($db->data_cache['table_names']);
CompanyCustomerGroupsSchema::assertValid($db,$p);
$groups=new CompanyCustomerGroups($db,$p);
$db->query("INSERT INTO {$p}customers_groups(name) VALUES('Legacy group')");$legacy=(int)$db->insert_id();
essentialThrows(fn()=>$groups->save(41,12,'A group'),'company_client_access_denied','customer edit is not catalog administration');
foreach([41,82] as $issuer)$db->query("INSERT INTO {$p}issuers_resource_permissions VALUES(?,12,'customers','manage_groups')",[$issuer]);
$ga=$groups->save(41,12,'Same label');$gb=$groups->save(82,12,'Same label');
essentialCheck($ga!==$gb&&$groups->save(41,12,'Same label')===$ga,'catalog IDs scoped and exact replay idempotent');
$rows=$groups->all(41,12);essentialCheck(count($rows)===1&&$rows[0]['id']===$ga,'native group list excludes B and unowned legacy');
essentialThrows(fn()=>$groups->save(82,12,'Foreign',$ga,$rows[0]['revision']),'company_client_access_denied','foreign group ID rejected');
$groups->save(41,12,'Renamed',$ga,$rows[0]['revision']);
essentialThrows(fn()=>$groups->save(41,12,'Stale',$ga,$rows[0]['revision']),'company_client_stale','stale group update rejected');
$client=$clients->create(41,12,['company'=>'Group owner']);
IssuerTransaction::run($db,$p,CompanyCustomerGroups::TABLES,fn()=>$groups->syncOwned(41,12,$client,[$ga]));
essentialCheck((int)$groups->memberships(41,12,$client)[0]['groupid']===$ga,'membership uses native join table');
essentialThrows(fn()=>IssuerTransaction::run($db,$p,CompanyCustomerGroups::TABLES,fn()=>$groups->syncOwned(41,12,$client,[$gb])),'company_client_access_denied','foreign group assignment rejected');
essentialThrows(fn()=>IssuerTransaction::run($db,$p,CompanyCustomerGroups::TABLES,fn()=>$groups->syncOwned(41,12,$client,[$legacy])),'company_client_access_denied','legacy groups never adopted');
essentialThrows(fn()=>$groups->memberships(82,12,$client),'company_client_access_denied','foreign client group projection rejected');
$fresh=$groups->all(41,12)[0];
essentialThrows(fn()=>$groups->delete(82,12,$ga,$fresh['revision']),'company_client_access_denied','foreign delete denied');
$before=$groups->all(41,12);$db->failOn='INSERT INTO '.$p.'issuers_audit';
essentialThrows(fn()=>$groups->save(41,12,'Rollback group'),'issuer_storage_failed','audit failure rolls back group and ownership');$db->failOn=null;
essentialCheck($groups->all(41,12)===$before,'catalog unchanged after rollback');
$fresh=$groups->all(41,12)[0];$groups->delete(41,12,$ga,$fresh['revision']);
essentialCheck($groups->all(41,12)===[]&&$groups->memberships(41,12,$client)===[],'owned group delete removes only owned memberships');
essentialCheck(count($groups->all(82,12))===1&&(int)$db->query("SELECT COUNT(*) n FROM {$p}customers_groups WHERE id=?",[$legacy])->row()->n===1,'B and legacy groups preserved');
$db->query("DELETE FROM {$p}issuers_resource_permissions WHERE issuer_id=41 AND staff_id=12 AND capability='manage_groups'");
essentialThrows(fn()=>$groups->save(41,12,'Revoked'),'company_client_access_denied','revoked catalog grant effective');
echo "Native customer group ownership tests passed.\n";
